def next_smallest_palindrome(num):
    numstr = str(num)
    length = len(numstr)

    # Helper function to create the next palindrome
    def create_palindrome(s, is_odd):
        if is_odd:
            return s + s[-2::-1]
        else:
            return s + s[-1::-1]

    # Check if the number is already a palindrome
    if numstr == numstr[::-1]:
        # Generate the next palindrome
        num += 1
        numstr = str(num)

    # Generate the next possible palindrome
    for i in range(1, length + 1):
        half = numstr[:(length + i) // 2]
        half = str(int(half) + 1)
        pal = create_palindrome(half, i % 2 == 1)
        if len(pal) > length:
            return int(pal)
        if int(pal) > num:
            return int(pal)

    # If all else fails, return the next palindrome by incrementing
    return int(create_palindrome(numstr, True))
```

