def get_total_number_of_sequences(m, n):
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        dp[i][1] = 1  # A sequence of length 1 can be any number from 1 to m

    for length in range(2, n + 1):
        for last in range(1, m + 1):
            # The previous number must be at least 1 and at most last // 2
            for prev in range(1, last // 2 + 1):
                dp[last][length] += dp[prev][length - 1]

    return dp[m][n]
