def max_product(arr):
    n = len(arr)
    # dp[i] will store the maximum product of an increasing subsequence ending at index i
    dp = [arr[i] for i in range(n)]

    for i in range(n):
        for j in range(i + 1, n):
            if arr[j] > arr[i]:
                # If the product of the subsequence ending at i multiplied by arr[j] is greater than current dp[j]
                if dp[i] * arr[j] > dp[j]:
                    dp[j] = dp[i] * arr[j]

    return max(dp)
```

